1	/* ===== Đi dạo: nạp mô hình người có xương (public/people/p<k>.glb) và một nhân vật đang diễn =====
2	   - stRigLoad(k): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải), nạp p<k>.glb một lần, nhớ đệm theo k.
3	     Lỗi bất kỳ (mạng, file hỏng, thiếu đoạn) → console.warn một lần cho mô hình đó, trả null, không thử lại trong phiên; promise không bao giờ bị từ chối.
4	   - stRigSource: chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn),
5	     vật liệu metalness 0, roughness 0.85; mảnh alpha (alphaMode MASK) giữ alphaTest, không trộn trong suốt. Tốc độ tự nhiên từng đoạn đọc từ extras.speed.
6	   - Làm nóng: sau khi nạp, stRigLoad chờ hàm do stRigSetWarm gắn (compileAsync theo cảnh chính, ≤ anim.warmMs) rồi mới trả nguồn (D-018).
7	   - StRig: một bản sao (SkeletonUtils.clone, dùng chung geometry / texture / vật liệu với nguồn) + AnimationMixer riêng.
8	     pose(): trọng số đích từ stClipMix (anim.ts), làm mượt về đích với hằng thời gian anim.fade; walk / jog / sprint đồng pha bằng một pha chung 0–1
9	     (đặt action.time = pha × thời lượng đoạn, timeScale 0 để mixer không tự tua); photo LoopOnce + clampWhenFinished, phát lại từ đầu mỗi lần chuyển sang dáng chụp ảnh.
10	     dt kẹp [0, stroll.dtMax] (tab ẩn rồi quay lại không làm nhảy pha). Không cấp phát mỗi khung (D-018).
11	   - Mô hình: mét, chân ở y = 0, mặt hướng +X (như hình khối), xương Rocketbox (Bip01_*). docs/superpowers/specs/2026-11-12-nguoi-di-dao-that-design.md §5, §7 */
12	import * as THREE from 'three';
13	import { CONFIG } from '../../config';
14	import { ST_CLIPS, stClipMix, type StClipMix } from './anim';
15	
16	const A = CONFIG.stroll.anim, NC = ST_CLIPS.length;
17	const ST_LOCO0 = 1, ST_LOCO1 = 3, ST_PHOTO = 4;   // chỉ số trong ST_CLIPS: walk..sprint, photo (idle = 0)
18	
19	export interface StRigSource {
20	  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
21	  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
22	  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
23	  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
24	  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
25	}
26	
27	/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
28	export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
29	  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
30	  for (let i = 0; i < NC; i++) {
31	    const c = clips.find(x => x.name === ST_CLIPS[i]);
32	    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
33	    out.push(c);
34	    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
35	  }
36	  scene.traverse((o) => {
37	    o.layers.set(1);
38	    const m = o as THREE.Mesh;
39	    if (!m.isMesh) return;
40	    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
41	    const mats = Array.isArray(m.material) ? m.material : [m.material];
42	    for (const mat of mats) {
43	      const s = mat as THREE.MeshStandardMaterial;
44	      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
45	      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
46	    }
47	  });
48	  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
49	}
50	
51	const cache = new Map<number, Promise<StRigSource | null>>();
52	
53	/* Làm nóng shader (D-018): stroll/index.ts gắn hàm biên dịch sẵn chương trình của cảnh nguồn theo đèn / sương / bóng của cảnh chính
54	   (rig.ts không import renderer để chạy được trong unit test). Chưa gắn, lỗi hoặc quá anim.warmMs: bỏ qua, nguồn vẫn dùng được */
55	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
56	export function stRigSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
57	async function stRigWarm(o: THREE.Object3D): Promise<void> {
58	  if (!warm) return;
59	  let timer = 0;
60	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, A.warmMs) as unknown as number; })]); }
61	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
62	  finally { clearTimeout(timer); }
63	}
64	
65	/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
66	export function stRigLoad(model: number): Promise<StRigSource | null> {
67	  let p = cache.get(model);
68	  if (p) return p;
69	  p = (async () => {
70	    try {
71	      const path = A.models[model];
72	      if (!path) throw new Error('không có mô hình số này');
73	      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
74	      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
75	      const speeds: Record<string, number> = {};
76	      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
77	      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
78	      const src = stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
79	      await stRigWarm(src.scene);   // nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
80	      return src;
81	    } catch (e) {
82	      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
83	      return null;
84	    }
85	  })();
86	  cache.set(model, p);
87	  return p;
88	}
89	
90	/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
91	export class StRig {
92	  readonly root: THREE.Object3D;
93	  readonly src: StRigSource;
94	  readonly mixer: THREE.AnimationMixer;
95	  readonly actions: THREE.AnimationAction[] = [];
96	  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
97	  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
98	  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
99	  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
100	  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
101	  private photo = false;                // khung trước đang ở dáng chụp ảnh
102	
103	  constructor(src: StRigSource) {
104	    this.src = src;
105	    this.root = src.clone(src.scene);
106	    this.root.name = 'stroll-rig';
107	    this.mixer = new THREE.AnimationMixer(this.root);
108	    for (let i = 0; i < NC; i++) {
109	      const a = this.mixer.clipAction(src.clips[i]);
110	      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
111	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
112	      a.enabled = false; a.setEffectiveWeight(0); a.play();
113	      this.actions.push(a);
114	    }
115	  }
116	
117	  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
118	  pose(pose: number, speed: number, dt: number): void {
119	    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
120	    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
121	    stClipMix(pose, speed, this.src.natural, mix);
122	    const toPhoto = mix.w[ST_PHOTO] === 1;
123	    if (toPhoto && !this.photo) acts[ST_PHOTO].reset();   // chuyển sang chụp ảnh: giơ máy lại từ đầu
124	    this.photo = toPhoto;
125	    const k = this.fresh || !(A.fade > 0) ? 1 : 1 - Math.exp(-d / A.fade);   // fade ≤ 0: chuyển tức thì (tránh 0/0 = NaN khi d = 0)
126	    this.fresh = false;
127	    for (let i = 0; i < NC; i++) w[i] += (mix.w[i] - w[i]) * k;
128	    if (mix.loco) this.rate = mix.rate;   // đang rời nhóm di chuyển: giữ nhịp cũ trong lúc mờ dần
129	    let lw = 0, dur = 0;
130	    for (let i = ST_LOCO0; i <= ST_LOCO1; i++) { lw += w[i]; dur += w[i] * clips[i].duration; }
131	    if (lw > 1e-4 && dur > 1e-6) {
132	      const p = this.phase + d * this.rate / (dur / lw);   // chu kỳ của hỗn hợp = trung bình thời lượng theo trọng số
133	      this.phase = p - Math.floor(p);
134	    }
135	    for (let i = 0; i < NC; i++) {
136	      const a = acts[i], on = w[i] > 1e-4;
137	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.time = this.phase * clips[i].duration;
138	      if (on !== a.enabled) a.enabled = on;   // đoạn không trọng số: mixer bỏ qua, không tính
139	      a.setEffectiveWeight(on ? w[i] : 0);
140	    }
141	    this.mixer.update(d);
142	  }
143	
144	  /* Đặt lại như vừa tạo: lần pose kế đặt thẳng trọng số đích */
145	  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }
146	
147	  /* Gỡ khỏi nhóm, bỏ mixer, giải phóng skeleton riêng của bản sao (SkeletonUtils.clone tạo skeleton mới cho mỗi SkinnedMesh; renderer cấp boneTexture cho từng cái).
148	     geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
149	  dispose(): void {
150	    this.mixer.stopAllAction();
151	    this.mixer.uncacheRoot(this.root);
152	    this.root.removeFromParent();
153	    const seen = new Set<THREE.Skeleton>();
154	    this.root.traverse((o) => {
155	      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
156	      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
157	    });
158	  }
159	}
160

1	/* ===== Người treo dù: một bộ nhân vật + trang bị gắn dưới một cánh (src/explore/pilot/rig.ts) =====
2	   Cây nút (hệ group dù: +X bay, +Y lên, +Z phải):
3	     ex-pilot (Group, lớp 1)
4	     ├─ wing  (Object3D tĩnh tại gốc group dù: đầu trên của dây treo / dây phanh)
5	     ├─ swing (Group tại điểm tụ dây = đỉnh riser, (0, exHangY + riser, 0); lắc con lắc swingRoll / Pitch / Yaw; cũng là xương `hang` của trang bị)
6	     │  └─ bản sao nhân vật (gốc tại hông: (−hang.fore, −riser − hang.up, 0) so với swing), AnimationMixer phát `sit`
7	     └─ gear (SkinnedMesh trang bị, hình học dùng chung mọi dù, Skeleton riêng)
8	   Người treo quay quanh điểm tụ dây (cả riser, carabiner, người đi cùng nhau), dây treo trên đó đứng yên trong hệ dù.
9	   Quai phanh treo theo riser nên tính trong hệ lắc: điểm nắm = hông + (toggle.fore + hang.fore, toggle.up + hang.up − phanh·travel, ±toggle.half).
10	   Trang bị: Skeleton [wing, hang, Pelvis, Spine2, L Hand, R Hand, L Thigh, R Thigh, pack]; boneInverses = nghịch đảo ma trận từng xương trong hệ ex-pilot
11	   đo ở tư thế bay nền (pose 0, phanh nền, sau mixer.update(0)), bindMatrix đơn vị ⇒ dù ở đâu trong thế giới cũng đúng. Không cấp phát mỗi khung. */
12	import * as THREE from 'three';
13	import { CONFIG } from '../../config';
14	import { exHangY } from '../glider';
15	import { PlReact, type PlSignals } from './react';
16	import { PlBones } from './bones';
17	import { plGearGeometry, plGearMaterial, type PlGearRest } from './gear';
18	import type { PlSource } from './load';
19	
20	const _tL = new THREE.Vector3(), _tR = new THREE.Vector3();
21	
22	/* Hình học trang bị dùng chung theo nguồn (vị trí nghỉ giống nhau mọi dù: cùng mô hình, cùng tư thế nền) */
23	const gearGeo = new WeakMap<PlSource, THREE.BufferGeometry>();
24	
25	export class PlRig {
26	  readonly group = new THREE.Group();
27	  readonly wing = new THREE.Object3D();
28	  readonly swing = new THREE.Group();
29	  readonly root: THREE.Object3D;
30	  readonly mixer: THREE.AnimationMixer;
31	  readonly react: PlReact;
32	  readonly bones: PlBones;
33	  readonly gear: THREE.SkinnedMesh;
34	  readonly pack = new THREE.Object3D();
35	  readonly rest: PlGearRest;
36	
37	  constructor(src: PlSource, seed: number) {
38	    const P = CONFIG.explore.pilot;
39	    this.group.name = 'ex-pilot';
40	    this.wing.name = 'pl-wing'; this.swing.name = 'pl-swing'; this.pack.name = 'pl-pack';
41	    this.group.add(this.wing, this.swing);
42	    this.swing.position.set(0, exHangY + P.riser, 0);
43	    this.root = src.clone(src.scene);
