1	/* ===== Người treo dù: IK hai khớp giải tích (src/explore/pilot/ik.ts) =====
2	   Thuần số học, không import three, không cấp phát: vectơ là mảng số (ArrayLike / number[]) dùng lại.
3	   Dùng cho cánh tay (vai → khuỷu → cổ tay) tới quai phanh; đích ngoài tầm được kẹp về tầm với để khớp không gãy. */
4	
5	/* Hai khớp: gốc a, dài l1 (a → khuỷu), l2 (khuỷu → đầu mút), đích t, cực p là ĐIỂM trong cùng hệ tọa độ (khuỷu nằm lệch về phía p so với đường a → đích).
6	   Ghi vị trí khuỷu vào outElbow, đầu mút (đã kẹp vào tầm với) vào outEnd; trả true nếu đích nằm trong tầm [|l1 − l2|, (l1 + l2) × 0.999] */
7	export function plTwoBone(a: ArrayLike<number>, l1: number, l2: number, t: ArrayLike<number>, p: ArrayLike<number>, outElbow: number[], outEnd: number[]): boolean {
8	  const ax = a[0], ay = a[1], az = a[2];
9	  let dx = t[0] - ax, dy = t[1] - ay, dz = t[2] - az;
10	  let dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
11	  const maxR = (l1 + l2) * 0.999, minR = Math.abs(l1 - l2) * 1.001 + 1e-6;
12	  const inReach = dist >= minR && dist <= maxR;
13	  let ux: number, uy: number, uz: number;
14	  if (dist > 1e-9) { ux = dx / dist; uy = dy / dist; uz = dz / dist; }
15	  else { ux = 1; uy = 0; uz = 0; dist = 0; }   // đích trùng gốc: chọn hướng tùy ý, vẫn không NaN
16	  const c = dist > maxR ? maxR : dist < minR ? minR : dist;
17	  /* Khuỷu: x dọc trục a → đích, h vuông góc theo hướng cực */
18	  const x = (l1 * l1 - l2 * l2 + c * c) / (2 * c);
19	  const h = Math.sqrt(Math.max(0, l1 * l1 - x * x));
20	  let px = p[0] - ax, py = p[1] - ay, pz = p[2] - az;
21	  const along = px * ux + py * uy + pz * uz;
22	  px -= along * ux; py -= along * uy; pz -= along * uz;   // phần cực vuông góc với trục
23	  let pl = Math.sqrt(px * px + py * py + pz * pz);
24	  if (pl < 1e-6) {   // cực song song trục: lấy trục tọa độ ít song song nhất
25	    const bx = Math.abs(ux) < 0.9 ? 1 : 0, by = bx ? 0 : 1;
26	    px = by * uz - 0 * uy; py = 0 * ux - bx * uz; pz = bx * uy - by * ux;   // b × u với b = (bx, by, 0)
27	    pl = Math.sqrt(px * px + py * py + pz * pz) || 1;
28	  }
29	  px /= pl; py /= pl; pz /= pl;
30	  outElbow[0] = ax + ux * x + px * h; outElbow[1] = ay + uy * x + py * h; outElbow[2] = az + uz * x + pz * h;
31	  outEnd[0] = ax + ux * c; outEnd[1] = ay + uy * c; outEnd[2] = az + uz * c;
32	  return inReach;
33	}
