120	    o.quaternion.premultiply(_q2);
121	  }
122	  /* Đặt hướng xương o trong hệ C bằng Q (tuyệt đối) */
123	  private setC(o: THREE.Object3D, Q: THREE.Quaternion): void {
124	    this.qC(o.parent, _q);
125	    o.quaternion.copy(_q.invert().multiply(Q));
126	  }
127	  private rotE(o: THREE.Object3D | null, x: number, y: number, z: number): void {
128	    if (!o || (x === 0 && y === 0 && z === 0)) return;
129	    this.rotC(o, _qr.setFromEuler(_e.set(x, y, z, 'YZX')));
130	  }
131	
132	  /* Số đo cố định từ tư thế `sit` (rig.ts gọi một lần sau mixer.update(0), trước apply): độ dài tay, trục bản lề khuỷu, trục bàn tay, điểm nắm */
133	  measure(): void {
134	    this.updateMatrices();
135	    const A = CONFIG.explore.pilot.arm;
136	    const pa = new THREE.Vector3(), pf = new THREE.Vector3(), ph = new THREE.Vector3(), n = new THREE.Vector3(), Q = new THREE.Quaternion();
137	    for (const a of this.arms) {
138	      this.pC(a.up, pa); this.pC(a.fore, pf); this.pC(a.hand, ph);
139	      a.l1 = Math.max(0.05, pa.distanceTo(pf)); a.l2 = Math.max(0.05, pf.distanceTo(ph));
140	      const du = pf.clone().sub(pa).normalize(), df = ph.clone().sub(pf).normalize();
141	      n.crossVectors(du, df);
142	      if (n.lengthSq() < 1e-6) n.set(0, a.side > 0 ? -1 : 1, 0).cross(du);   // tay duỗi thẳng ở `sit`: lấy bản lề nằm ngang (dự phòng, không NaN)
143	      n.normalize();
144	      this.qC(a.up, Q).invert(); a.dU.copy(du).applyQuaternion(Q); a.nU.copy(n).applyQuaternion(Q);
145	      this.qC(a.fore, Q).invert(); a.dF.copy(df).applyQuaternion(Q); a.nF.copy(n).applyQuaternion(Q);
146	      /* bàn tay: hướng ngón = cổ tay → gốc ngón giữa; pháp tuyến lòng bàn tay = side · (trỏ − út) × hướng ngón (đúng cho cả hai tay); thiếu ngón thì nối dài cẳng tay, lòng bàn tay úp */
147	      const mid = a.fingers[2][0], idx = a.fingers[1][0], pin = a.fingers[4][0];
148	      const fd = new THREE.Vector3(), palm = new THREE.Vector3(0, -1, 0);
149	      if (mid) fd.copy(this.pC(mid, new THREE.Vector3())).sub(ph); else fd.copy(df).multiplyScalar(0.09);
150	      const reach = Math.max(0.03, fd.length()); fd.normalize();
151	      if (idx && pin) { palm.copy(this.pC(idx, new THREE.Vector3())).sub(this.pC(pin, new THREE.Vector3())).cross(fd).multiplyScalar(a.side); if (palm.lengthSq() < 1e-10) palm.set(0, -1, 0); }
152	      palm.addScaledVector(fd, -palm.dot(fd)).normalize();
153	      if (!fin3(palm) || palm.lengthSq() < 0.5) palm.set(0, -1, 0);
154	      const g = fd.clone().multiplyScalar(reach * A.grip[0]).addScaledVector(palm, A.grip[1]);
155	      this.qC(a.hand, Q).invert();
156	      a.fH.copy(fd).applyQuaternion(Q); a.nH.copy(palm).applyQuaternion(Q); a.gH.copy(g).applyQuaternion(Q);
157	      a.hasD = false;
158	    }
159	  }
160	
161	  /* Áp tư thế: pose (react.ts, góc cộng thêm) + đích hai quai phanh tL / tR (điểm nắm, hệ C) */
162	  apply(p: PlPose, tL: THREE.Vector3, tR: THREE.Vector3): void {
163	    const P = CONFIG.explore.pilot, B = P.base;
164	    /* 1) hông ngả ra sau: xoay quanh +Z dương đưa thân trên về −X, đùi nâng lên (bù ở bước 4) */
165	    this.rotE(this.pelvis, 0, 0, B.recline);
166	    /* 2) ba đốt sống: nghiêng trái = quay âm quanh +X, chúi trước = quay âm quanh +Z, vai xoay trái = quay dương quanh +Y */
167	    const k = 1 / this.spines.length;
168	    for (const s of this.spines) this.rotE(s, -p.spineRoll * k, p.spineTwist * k, -(p.spinePitch + B.spine) * k);
169	    /* 3) đầu: quay, nghiêng bù, cúi nhìn trước (bù độ ngả) */
170	    this.rotE(this.neck, 0, 0, -B.neck);
171	    this.rotE(this.head, -p.headRoll, p.headYaw, -B.head);
172	    /* 4) chân: đùi (dạng: trái quay dương quanh +Y; đưa ngang theo legSide; gập hông quanh +Z), gối (gập = quay âm quanh +Z), bàn chân */
173	    for (let i = 0; i < 2; i++) {
174	      const side = i ? 1 : -1, knee = i ? p.kneeR : p.kneeL;
175	      this.rotE(this.thigh[i], 0, p.legSide - side * (p.legSplit + B.legSplit), B.hip + p.legFore * B.legForeHip);
176	      this.rotE(this.calf[i], 0, 0, -(B.knee + knee) + p.legFore);
177	      this.rotE(this.foot[i], 0, 0, B.foot);
178	    }
179	    /* 5) xương đòn nâng vai khi tay lên quai: trái quay dương quanh +X */
180	    for (const a of this.arms) this.rotE(a.clav, -a.side * B.clavicle, 0, B.clavicleFore);
181	    /* 6) ba lô (xương phụ con của Spine2): nghiêng trái = âm quanh +X, chúi trước = âm quanh +Z */
182	    if (this.pack) {
183	      this.pack.quaternion.identity();
184	      this.rotE(this.pack, -p.packRoll, 0, -p.packPitch);
185	    }
186	    /* 7) tay */
187	    this.updateMatrices();
188	    this.ik(this.arms[0], tL); this.ik(this.arms[1], tR);
189	  }
190	
191	  /* Hướng bàn tay mong muốn D (hệ C) khi cẳng tay theo hướng d2: ngón theo cẳng tay nghiêng về trước / lên / vào trong (arm.wrist), lòng bàn tay theo arm.palm */
192	  private handD(a: PlArm, d2: THREE.Vector3): void {
193	    const W = CONFIG.explore.pilot.arm;
194	    _f.copy(d2).addScaledVector(AX, W.wrist[0]).addScaledVector(AY, W.wrist[1]).addScaledVector(AZ, -a.side * W.wrist[2]).normalize();
195	    _n.set(W.palm[0], W.palm[1], -a.side * W.palm[2]);
196	    mapAxes(a.D, a.fH, a.nH, _f, _n);
197	    a.hasD = true;
198	  }
199	
200	  /* IK một tay tới điểm nắm t (hệ C). Ba lượt: đích cổ tay = t − D·gH với D của lượt trước */
201	  private ik(a: PlArm, t: THREE.Vector3): void {
202	    const W = CONFIG.explore.pilot.arm, F = CONFIG.explore.pilot.finger;
203	    a.target.copy(t);
204	    const A = this.pC(a.up, _A);
205	    _pole[0] = A.x + W.pole[0]; _pole[1] = A.y + W.pole[1]; _pole[2] = A.z + a.side * W.pole[2];
206	    _sh[0] = A.x; _sh[1] = A.y; _sh[2] = A.z;
207	    if (!a.hasD) this.handD(a, _d2.copy(t).sub(A).normalize());
208	    for (let it = 0; it < 3; it++) {
209	      _g.copy(a.gH).applyQuaternion(a.D);
210	      _W.copy(t).sub(_g);
211	      _wt[0] = _W.x; _wt[1] = _W.y; _wt[2] = _W.z;
212	      plTwoBone(_sh, a.l1, a.l2, _wt, _pole, a.elbow, a.end);
213	      _E.fromArray(a.elbow); _W.fromArray(a.end);
214	      _d2.copy(_W).sub(_E).normalize();
215	      if (fin3(_d2)) this.handD(a, _d2);
216	    }
217	    _d1.copy(_E).sub(A).normalize();
218	    _nn.crossVectors(_d1, _d2);
219	    if (_nn.lengthSq() < 1e-8) _nn.set(W.pole[0], W.pole[1], a.side * W.pole[2]).cross(_d1);   // tay duỗi thẳng: bản lề vuông góc với mặt phẳng chứa cực
220	    _nn.normalize();
221	    if (!fin3(_d1) || !fin3(_d2) || !fin3(_nn)) return;
222	    this.setC(a.up, mapAxes(_QU, a.dU, a.nU, _d1, _nn));
223	    mapAxes(_QF, a.dF, a.nF, _d2, _nn);
224	    /* chia phần xoắn quanh trục cẳng tay giữa cẳng tay và cổ tay (arm.twist), da cổ tay không xoắn hết một chỗ */
225	    _q3.copy(_QF).invert().multiply(a.D);                        // bàn tay so với cẳng tay (hệ cục bộ cẳng tay)
226	    let tw = 2 * Math.atan2(_q3.x * a.dF.x + _q3.y * a.dF.y + _q3.z * a.dF.z, _q3.w);
227	    if (tw > Math.PI) tw -= 2 * Math.PI; else if (tw < -Math.PI) tw += 2 * Math.PI;
228	    _QF.premultiply(_qr.setFromAxisAngle(_d2, tw * W.twist));
229	    this.setC(a.fore, _QF);
230	    this.setC(a.hand, a.D);
231	    /* ngón co quanh trục ngang lòng bàn tay (hướng ngón × pháp tuyến lòng bàn tay: quay dương đưa ngón vào lòng bàn tay); ngón cái thêm xoay quanh hướng ngón để ôm quai */
232	    _f.copy(a.fH).applyQuaternion(a.D); _n.copy(a.nH).applyQuaternion(a.D);
233	    _ax.crossVectors(_f, _n).normalize();
234	    for (let f = 1; f < 5; f++) { const ch = a.fingers[f]; for (let j = 0; j < ch.length; j++) this.rotC(ch[j], _qr.setFromAxisAngle(_ax, F.curl[j])); }
235	    const th = a.fingers[0];
236	    if (th.length) {
237	      this.rotC(th[0], _qr.setFromAxisAngle(_f, -a.side * F.thumbRoll));
238	      for (let j = 0; j < th.length; j++) this.rotC(th[j], _qr.setFromAxisAngle(_ax, F.thumb[j]));
239	    }
240	  }
241	
242	  /* m — khoảng cách điểm nắm thật (xương bàn tay + D·gH) tới quai phanh, sau khi đã cập nhật ma trận */
243	  handErr(i: number): number {
244	    const a = this.arms[i];
245	    this.updateMatrices();
246	    const h = this.pC(a.hand, new THREE.Vector3());
247	    const g = a.gH.clone().applyQuaternion(this.qC(a.hand, new THREE.Quaternion()));
248	    return h.add(g).distanceTo(a.target);
249	  }
250	}
