1	/* ============================ Lái xe máy: điều phối chế độ (lái một mình, máy tính) ============================
2	   Spec D-040. Cấu trúc theo explore/drive/index.ts; dùng lại các phần thuần của chế độ ô tô (mạng đường, va chạm, camera sau xe, HUD),
3	   drive/* không bao giờ import ngược từ bike/*.
4	   - Mạng đường DÙNG CHUNG với ô tô: drEnsureNet() của drive/index.ts (dựng một lần cho cả trang; drCollectRuntime chỉ push, dựng net thứ hai sẽ nhân đôi vật cản).
5	   - Thân va chạm: start() đặt drUseBody(BK_BODY), stop() trả DR_CAR_BODY (drive.start() cũng tự đặt lại thân ô tô).
6	   - Mỗi khung: phím → BkInput (keys.ts), grip = 1 (Task 7 nối thời tiết), bkStep với hộp xe tự động gần xe (trNearby), hình xe (model.ts),
7	     camera góc thứ ba = drCamPlace với CONFIG.bike.cam3, controls.target theo xe (tâm vùng bóng đổ), HUD (đồng hồ + bản đồ nhỏ của ô tô), exNightStep(dt, false).
8	   - Phím (theo e.code, chỉ khi đang lái, bỏ ô nhập và tổ hợp Ctrl / Meta / Alt; blur / ẩn tab nhả hết): R về làn (bkRecover), Q / E xi nhan trái / phải (bkSignal),
9	     V đổi góc nhìn (góc thứ nhất ở Task 5, giờ chỉ có góc thứ ba). Còi H: âm thanh ở Task 8.
10	   - Lớp body 'explore drive bike': khung HUD #drHud và các quy tắc CSS của body.drive áp nguyên; 'bike' cho phần riêng về sau.
11	   - Thoát: explore.exit() gọi bike.stop() rồi tải lại trang. Chưa có: nhiều người (Task 10), cảm ứng (Task 9). Mô hình thật: model.ts (làm nóng qua bkModelSetWarm bên dưới).
12	   Mỗi khung không cấp phát (D-018). */
13	import type * as THREE from 'three';
14	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
15	import { composer, onResize } from '../../core/postprocessing';
16	import { cam } from '../../views/state';
17	import { CONFIG } from '../../config';
18	import { driveView } from '../../environment/driveRoads';
19	import { drSetGate, type DrNet } from '../drive/net';
20	import { DR_GATE_SWING } from '../drive/roadData';
21	import { drUseBody, DR_CAR_BODY, type DrBox } from '../drive/collide';
22	import { drCamPlace, drCamDrag, type DrCam } from '../drive/camera';
23	import { drBindDrop } from '../drive/keys';
24	import { drHudShow, drHudHide, drHudUpdate, type DrMapDot } from '../drive/hud';
25	import { drEnsureNet } from '../drive';
26	import { trNearby } from '../../common/trafficQuery';
27	import { exNightStep } from '../nightShows';
28	import { bkCreate, bkStep, bkRecover, bkSignal, bkPitch, BK_BODY, type BkState, type BkInput } from './motion';
29	import { bkInputFromKeys, BK_KEYS } from './keys';
30	import { BkBike, bkModelLoad, bkModelSetWarm } from './model';
31	import type { SwingController } from '../../bridges/song-han/SwingController';
32	
33	/* Làm nóng shader của xe máy (D-018), như drive/index.ts drCarSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
34	   đèn / sương / bóng lấy từ cảnh chính, camera chính. Nhóm làm nóng (mô hình, mặt đồng hồ, hình tạm, tấm bóng) do model.ts dựng, không thêm vào scene */
35	bkModelSetWarm(async (o: THREE.Object3D) => {
36	  const rt = renderer.getRenderTarget();
37	  renderer.setRenderTarget(null);
38	  const a = renderer.compileAsync(o, camera, scene);
39	  renderer.setRenderTarget(rt);
40	  await a;
41	  renderer.setRenderTarget(composer.readBuffer);
42	  const b = renderer.compileAsync(o, camera, scene);
43	  renderer.setRenderTarget(rt);
44	  await b;
45	});
46	
47	const BK_SOLO_SLOT = -1;   // bkCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot (trên Cầu Rồng, đi Đông, bên phải)
48	const K3 = CONFIG.bike.cam3;
49	const NO_DOTS: DrMapDot[] = [];   // lái một mình: bản đồ nhỏ không có xe người khác
50	
51	let net: DrNet | null = null;
52	let state: BkState | null = null;
53	let ctrl: SwingController | null = null;
54	let model: BkBike | null = null;   // hình xe của mình, dựng lần đầu vào chế độ
55	let view: 1 | 3 = 3;
56	const bkKeys = new Set<string>();   // e.code đang giữ
57	const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
58	const _inp: BkInput = { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 };   // đầu vào tái dùng mỗi khung
59	const boxes: DrBox[] = [];          // hộp xe tự động gần xe, tái dùng mỗi khung
60	let saved: { fov: number; near: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại
61	
62	const active = () => cam.mode === 'bike' && state !== null;
63	const inMode = () => active();     // chế độ xem (hết chỗ) ở Task 10
64	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
65	
66	/* Một bước: cổng nhịp quay, chuyển động (sơ tán nằm trong bkStep), hình xe, camera, HUD, hiệu ứng đêm */
67	function advance(dt: number, inp: BkInput): void {
68	  const s = state!, n = net!;
69	  if (ctrl) drSetGate(n, DR_GATE_SWING, ctrl.state !== 'CLOSED');
70	  bkStep(s, inp, n, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
71	  model!.place(s);
72	  drCamPlace(camera, s, camS, n, dt, false, K3);
73	  controls.target.set(s.x, s.y, s.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
74	  drHudUpdate(s, NO_DOTS);
75	  exNightStep(dt, false);
76	}
77	
78	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
79	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
80	  if (!net || !model) return;
81	  const s = bkCreate(net, BK_SOLO_SLOT);
82	  let gy = -Infinity;
83	  for (const p of net.pads) {
84	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
85	    gy = Math.max(gy, p.y(x, z));
86	  }
87	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
88	  bkPitch(s, net);
89	  state = s;
90	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
91	  model.place(s);
92	  drCamPlace(camera, s, camS, net, 0, true, K3);
93	  controls.target.set(s.x, s.y, s.z);
94	}
95	
96	export const bike = {
97	  active,
98	  inMode,
99	  get state(): BkState | null { return state; },
100	  get net(): DrNet | null { return net; },
101	  get model(): BkBike | null { return model; },   // hình xe của mình (test: real, anchors)
102	  get view(): 1 | 3 { return view; },
103	  /* Đổi góc nhìn: góc thứ nhất làm ở Task 5, giờ luôn góc thứ ba */
104	  setView(v: 1 | 3): void { view = v === 1 ? 3 : v; },
105	  /* Vào lái một mình */
106	  start(): void {
107	    drUseBody(BK_BODY);
108	    const n = drEnsureNet();
109	    net = n;
110	    state = bkCreate(n, BK_SOLO_SLOT);
111	    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
112	    if (!model) model = new BkBike();
113	    scene.add(model.group);
114	    model.place(state);
115	    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
116	    bkKeys.clear();
117	    drHudShow(n);
118	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
119	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
120	    camera.fov = K3.fov; onResize();          // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
121	    drCamPlace(camera, state, camS, n, 0, true, K3);
122	    controls.target.set(state.x, state.y, state.z);
123	    document.body.classList.add('explore', 'drive', 'bike');
124	  },
125	  update(dt: number): void {
126	    if (!active()) return;
127	    bkInputFromKeys(bkKeys, _inp);
128	    _inp.grip = 1;                            // Task 7: theo thời tiết (weatherU.uWet), khô trong hầm kín
129	    advance(dt, _inp);
130	  },
131	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
132	  afterRender(): void { /* chưa có việc */ },
133	  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
134	  stop(): void {
135	    if (state === null) return;
136	    state = null; bkKeys.clear();
137	    drHudHide();
138	    model?.group.removeFromParent();
139	    driveView.far = 1;
140	    drUseBody(DR_CAR_BODY);
141	    document.body.classList.remove('drive', 'bike');
142	    if (saved) {
143	      if (!saved.explore) document.body.classList.remove('explore');
144	      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
145	      saved = null;
146	    }
147	    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
148	  },
149	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
150	  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
151	  placeAt: bkPlaceAt,
152	  /* Nạp mô hình thật (scooter.glb) sớm, khi chọn thẻ Xe máy */
153	  preload(): void { void bkModelLoad(); }
