156	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem (Task 10) */
157	export function setupBike(c: SwingController, onExit: () => void): void {
158	  ctrl = c; void onExit;
159	  window.addEventListener('keydown', (e) => {
160	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
