1	/* ============================ Lái xe máy: hình xe (hình tạm + mô hình thật public/bike/scooter.glb) ============================
2	   BkBike: một nhóm đặt ở điểm giữa hai vệt bánh trên mặt đường (tâm thân xe, y = mặt đường), xoay yaw quanh Y rồi pitch quanh Z cục bộ (như DrCar);
3	   bên trong một nút cuộn `lean` quanh trục dọc X cục bộ đi qua mặt đường (đường chạm đất): lean > 0 nghiêng trái (−Z cục bộ khi mũi +X), nên
4	   cuộn là −lean quanh +X. Tấm bóng mờ ở nhóm ngoài (không cuộn theo xe).
5	   - Hình tạm: hình 'bike' của common/vehicles/shapes.ts (xe tay ga + người lái đội mũ, mũi +X, mặt đường y = 0) chép ra, tô màu các phần
6	     màu theo instance (sơn, áo, mũ) bằng CONFIG.bike.model.temp, giãn theo X cho đúng chiều dài thân va chạm (CONFIG.bike.body.length). Một Mesh.
7	   - Mô hình thật (scripts/bike/convert.py, npm run gen:bike): bkModelLoad() import() động GLTFLoader, nạp một lần, nhớ đệm; lỗi / quá model.timeoutMs →
8	     console.warn một lần, null; promise không bao giờ bị từ chối; nạp xong muộn thì xe đang có vẫn đổi sang mô hình thật (`late`, như drive/car.ts).
9	     Cây nút: scooter → body (4 lưới: body, lamp_tail, lamp_sig_l, lamp_sig_r; neo foot_l / foot_r / seat / eye), front (gốc trên trục cổ lái, userData.axis;
10	     4 lưới: trim, lamp_head, mirror, dash; neo grip_l / grip_r; wheel_f), wheel_r. Mỗi xe một bản sao (dùng chung hình học / vật liệu nguồn), lớp 1, không bóng.
11	     Lệnh vẽ mô hình thật: 8 thân + 2 bánh + 1 bóng = 11 (hình tạm: 2).
12	   - Đèn: vá phát sáng bằng onBeforeCompile đọc shared.uNight (không PointLight): hệ số = max(uNight · night, uOn). Đèn pha luôn sáng (uOn = headDay);
13	     đèn hậu chỉ sáng đêm, phanh thì uOn = tailBrake; xi nhan uOn = sigOn ở nửa chu kỳ sáng. Bản "sáng" là vật liệu thứ hai cùng customProgramCacheKey,
14	     chỉ khác uniform: đổi tham chiếu vật liệu của lưới, không biên dịch lại. Xi nhan nháy theo shared.uTime (thời gian khung, main.ts), không setInterval.
15	   - Mặt đồng hồ: mỗi xe một MeshBasicMaterial (dashMat) thay vật liệu `dash` của nguồn; UV 0..1 kiểu glTF (v = 0 phía trước xe, u tăng sang phải người lái):
16	     texture canvas gắn sau phải đặt flipY = false để đỉnh canvas nằm phía trước.
17	   - place(): thân = vị trí · yaw · pitch · cuộn lean quanh đường chạm đất; `front` xoay `steer` (kẹp ±model.steerLock) quanh trục cổ lái; bánh lăn quanh Z cục bộ
18	     theo `wheel` (xe tiến: góc âm); susF trượt bánh trước dọc trục cổ lái (+ = nén), susR nâng bánh sau so với thân; phần trên lò xo (nút gốc scooter) xoay quanh Z
19	     và hạ / nâng cho đúng hai tâm bánh ở độ cao nghỉ (bánh luôn chạm đất, đầu / đuôi chúi theo giảm xóc).
20	   - anchors: neo cho người lái (Task 4). Trước khi có mô hình thật là nút rỗng ở gốc nút cuộn; đổi sang mô hình thì trỏ tới nút trong bản sao (đọc lại sau khi real).
21	   Không cấp phát mỗi khung (D-018). */
22	import * as THREE from 'three';
23	import { CONFIG } from '../../config';
24	import { shared } from '../../core/shared';
25	import { vhBuildTypeGeometry, Role } from '../../common/vehicles/shapes';
26	
27	export interface BkPlace { x: number; y: number; z: number; yaw: number; pitch: number; lean: number; steer: number; wheel: number; susF: number; susR: number; braking: boolean; sig: -1 | 0 | 1 }
28	export interface BkAnchors { gripL: THREE.Object3D; gripR: THREE.Object3D; footL: THREE.Object3D; footR: THREE.Object3D; seat: THREE.Object3D; eye: THREE.Object3D }
29	
30	const B = CONFIG.bike.body, M = CONFIG.bike.model;
31	const AXY = new THREE.Vector3(0, 1, 0), AXZ = new THREE.Vector3(0, 0, 1);
32	const ANCHORS: [keyof BkAnchors, string][] = [['gripL', 'grip_l'], ['gripR', 'grip_r'], ['footL', 'foot_l'], ['footR', 'foot_r'], ['seat', 'seat'], ['eye', 'eye']];
33	const _q = new THREE.Quaternion(), _v = new THREE.Vector3();
34	
35	/* ===== Vật liệu, hình học dùng chung ===== */
36	let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null;
37	
38	/* Hình tạm: chép hình 'bike' của đội xe, bỏ aRole, tô màu phần màu theo instance, giãn X về chiều dài thân */
39	function bkTempGeometry(): THREE.BufferGeometry {
40	  const g = vhBuildTypeGeometry('bike').clone();
41	  const role = g.getAttribute('aRole') as THREE.BufferAttribute, col = g.getAttribute('color') as THREE.BufferAttribute;
42	  const T = M.temp, paint = new THREE.Color(T.paint), shirt = new THREE.Color(T.shirt), helmet = new THREE.Color(T.helmet);
43	  for (let i = 0; i < role.count; i++) {
44	    const r = role.getX(i), c = r === Role.Paint ? paint : r === Role.Accent ? shirt : r === Role.Helmet ? helmet : null;
45	    if (c) col.setXYZ(i, c.r, c.g, c.b);
46	  }
47	  g.deleteAttribute('aRole');
48	  g.computeBoundingBox();
49	  const bb = g.boundingBox!, len = bb.max.x - bb.min.x;
50	  g.scale(B.length / len, 1, 1);                                     // mặt cắt giữ nguyên, chỉ dài theo thân va chạm
51	  g.computeBoundingBox(); g.computeBoundingSphere();
52	  return g;
53	}
54	
55	/* Tấm bóng mờ: như drShadowShared của ô tô (mép mềm hình vuông bo), cùng tham số vật liệu ⇒ cùng program */
56	function bkShadowShared(): void {
57	  if (shadowMat) return;
58	  const n = 32, d = new Uint8Array(n * n * 4);
59	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
60	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
61	    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;
62	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
63	  }
64	  const tex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); tex.needsUpdate = true;
65	  tex.magFilter = tex.minFilter = THREE.LinearFilter;
66	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: tex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
67	  shadowMat.name = 'bikeShadow';
68	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
69	}
70	function bkTempMaterial(): THREE.MeshStandardMaterial {
71	  if (!tempMat) { tempMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.1 }); tempMat.name = 'bikeTemp'; }
72	  return tempMat;
73	}
74	/* Vật liệu mặt đồng hồ: mỗi xe một bản (texture canvas riêng ở task sau), cùng tham số ⇒ cùng program */
75	function bkDashMaterial(): THREE.MeshBasicMaterial {
76	  const m = new THREE.MeshBasicMaterial({ color: M.dashColor });
77	  m.name = 'bikeDash';
78	  return m;
79	}
80	
81	/* ===== Vật liệu đèn: phát sáng × max(uNight · night, uOn); `night` nằm trong chuỗi shader nên khóa program theo `key` ===== */
82	function bkLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, on: number): void {
83	  const uOn = { value: on };
84	  m.onBeforeCompile = (s) => {
85	    s.uniforms.uNight = shared.uNight;
86	    s.uniforms.uOn = uOn;
87	    s.fragmentShader = 'uniform float uNight;\nuniform float uOn;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
88	      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uOn );`);
89	  };
90	  m.customProgramCacheKey = () => key;
91	  m.userData.lampOn = on;
92	}
93	
94	export interface BkSource {
95	  scene: THREE.Object3D;                       // cảnh gốc (không thêm vào cảnh; chỉ để sao chép)
96	  axis: THREE.Vector3;                         // trục cổ lái (đơn vị) trong hệ nút cha của front, hướng lên
97	  tail: THREE.Material; tailBrake: THREE.Material;
98	  sigL: THREE.Material; sigLOn: THREE.Material; sigR: THREE.Material; sigROn: THREE.Material;
99	}
100	
101	/* Chuẩn hóa cảnh đã nạp thành nguồn dùng chung. Thiếu nút / vật liệu / trục thì ném lỗi (bkModelLoad bắt, trả null) */
102	export function bkModelSource(scene: THREE.Object3D): BkSource {
103	  for (const n of ['body', 'front', 'wheel_f', 'wheel_r', ...ANCHORS.map((a) => a[1])]) if (!scene.getObjectByName(n)) throw new Error(`thiếu nút ${n}`);
104	  const a = scene.getObjectByName('front')!.userData.axis as number[] | undefined;
105	  if (!Array.isArray(a) || a.length !== 3) throw new Error('front thiếu userData.axis');
106	  const axis = new THREE.Vector3(a[0], a[1], a[2]).normalize();
107	  const mats = new Map<string, THREE.MeshStandardMaterial>();
108	  scene.traverse((o) => {
109	    o.layers.set(1);
110	    const me = o as THREE.Mesh;
111	    if (!me.isMesh) return;
112	    me.castShadow = false; me.receiveShadow = false;
113	    const mat = me.material as THREE.MeshStandardMaterial;
114	    if (!mats.has(mat.name)) mats.set(mat.name, mat);
115	  });
116	  for (const n of ['lamp_head', 'lamp_tail', 'lamp_sig_l', 'lamp_sig_r', 'dash']) if (!mats.has(n)) throw new Error(`thiếu vật liệu ${n}`);
117	  bkLampPatch(mats.get('lamp_head')!, 'bkLampHead', M.headNight, M.headDay);
118	  const tail = mats.get('lamp_tail')!; bkLampPatch(tail, 'bkLampTail', M.tailNight, 0);
119	  const tailBrake = tail.clone(); bkLampPatch(tailBrake, 'bkLampTail', M.tailNight, M.tailBrake);   // cùng khóa: chỉ khác uniform
120	  const sig = (m: THREE.MeshStandardMaterial): THREE.MeshStandardMaterial => { bkLampPatch(m, 'bkLampSig', 0, 0); const on = m.clone(); bkLampPatch(on, 'bkLampSig', 0, M.sigOn); return on; };
121	  const sigL = mats.get('lamp_sig_l')!, sigR = mats.get('lamp_sig_r')!;
122	  return { scene, axis, tail, tailBrake, sigL, sigLOn: sig(sigL), sigR, sigROn: sig(sigR) };
123	}
124	
125	/* ===== Nạp (nhớ đệm), làm nóng ===== */
126	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
127	export function bkModelSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
128	
129	/* Làm nóng mọi thứ xe dùng: cảnh nguồn (thân, cổ lái, bánh, đèn), mặt đồng hồ (MeshBasicMaterial), hình tạm, tấm bóng. Bản đèn sáng / phanh cùng program
130	   với bản thường nên không cần. Gỡ cảnh nguồn ra (về không cha) sau khi làm nóng; chờ tối đa model.warmMs */
131	async function bkModelWarmAll(src: BkSource): Promise<void> {
132	  if (!warm) return;
133	  const g = new THREE.Group(), tg = bkTempGeometry(), dm = bkDashMaterial();
134	  g.add(new THREE.Mesh(tg, bkTempMaterial()));
135	  bkShadowShared(); g.add(new THREE.Mesh(shadowGeo!, shadowMat!));
136	  g.add(new THREE.Mesh(shadowGeo!, dm));
137	  g.add(src.scene);
138	  let timer = 0;
139	  try { await Promise.race([warm(g), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
140	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
141	  finally { clearTimeout(timer); g.remove(src.scene); tg.dispose(); dm.dispose(); }
142	}
143	
144	async function bkModelDefaultLoader(): Promise<THREE.Object3D> {
145	  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
146	  const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + M.url);
147	  return gltf.scene;
148	}
149	
150	let loader: () => Promise<THREE.Object3D> = bkModelDefaultLoader;
151	let cache: Promise<BkSource | null> | null = null;
152	let late: Promise<BkSource | null> | null = null;   // nạp không giới hạn giờ: BkBike đổi sang mô hình thật cả khi xong sau timeoutMs
153	
154	/* Nạp mô hình xe máy. Không bao giờ ném / từ chối: lỗi hoặc quá model.timeoutMs → warn một lần, null.
155	   Quá giờ chỉ là câu trả lời của bkModelLoad: việc nạp vẫn chạy tiếp, xe đang có (BkBike) đổi sang mô hình thật khi nó xong (late) */
156	export function bkModelLoad(): Promise<BkSource | null> {
157	  if (cache) return cache;
158	  const work = (async () => {
159	    const src = bkModelSource(await loader());
160	    await bkModelWarmAll(src);
161	    return src;
162	  })();
163	  const LATE = {} as BkSource;   // dấu quá giờ
164	  let timer = 0;
165	  const p = Promise.race([work, new Promise<BkSource>((r) => { timer = setTimeout(() => r(LATE), M.timeoutMs) as unknown as number; })])
166	    .then((s) => { if (s !== LATE) return s; console.warn(`Lái xe máy: nạp mô hình xe quá ${M.timeoutMs} ms, dùng hình tạm`); return null; },
167	      (e) => { console.warn('Lái xe máy: không nạp được mô hình xe, dùng hình tạm', e); return null; })
168	    .finally(() => clearTimeout(timer));
169	  late = work.catch(() => null);   // lỗi đã báo ở nhánh race
170	  cache = p;
171	  return p;
172	}
173	
174	/* Cho test: thay bộ nạp (null: mặc định), xóa đệm */
175	export function bkModelSetLoader(fn: (() => Promise<THREE.Object3D>) | null): void {
176	  loader = fn || bkModelDefaultLoader; cache = null; late = null;
177	}
178	
179	/* ===== Một xe máy ===== */
180	export class BkBike {
181	  readonly group = new THREE.Group();
182	  private readonly roll = new THREE.Group();                         // nút cuộn lean quanh đường chạm đất
183	  anchors: BkAnchors;
184	  dashMat: THREE.MeshBasicMaterial | null = null;
185	  private temp: THREE.Mesh | null;
186	  private tempGeo: THREE.BufferGeometry | null;
187	  private disposed = false;
188	  private src: BkSource | null = null;
189	  private root: THREE.Object3D | null = null;                        // bản sao `scooter`: phần trên lò xo
190	  private front: THREE.Object3D | null = null;
191	  private wheelF: THREE.Object3D | null = null;
192	  private wheelR: THREE.Object3D | null = null;
193	  private readonly frontQ0 = new THREE.Quaternion(); private readonly wfQ0 = new THREE.Quaternion(); private readonly wrQ0 = new THREE.Quaternion();
194	  private readonly frontP0 = new THREE.Vector3(); private readonly wfP0 = new THREE.Vector3(); private readonly wrP0 = new THREE.Vector3();
195	  private readonly axisF = new THREE.Vector3();                      // trục cổ lái trong hệ cục bộ của front lúc nghỉ
196	  private tailMeshes: THREE.Mesh[] = []; private sigLMeshes: THREE.Mesh[] = []; private sigRMeshes: THREE.Mesh[] = [];
197	  private brakingNow = false; private sigLNow = false; private sigRNow = false;
198	  private readonly last: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
199	  private placed = false;
200	
201	  constructor() {
202	    this.group.name = 'bike';
203	    this.group.add(this.roll);
204	    this.tempGeo = bkTempGeometry();
205	    this.temp = new THREE.Mesh(this.tempGeo, bkTempMaterial());
206	    this.temp.name = 'bike-temp';
207	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
208	    this.roll.add(this.temp);
209	    bkShadowShared();
210	    const sh = new THREE.Mesh(shadowGeo!, shadowMat!);
211	    sh.scale.set(B.length + 2 * M.shadow.pad, 1, B.width + 2 * M.shadow.pad);
212	    sh.position.y = M.shadow.lift;
213	    sh.layers.set(1); sh.castShadow = false; sh.receiveShadow = false; sh.renderOrder = 1;
214	    this.group.add(sh);
215	    const a = {} as BkAnchors;
216	    for (const [k, n] of ANCHORS) { const o = new THREE.Object3D(); o.name = 'bike-temp-' + n; this.roll.add(o); a[k] = o; }
217	    this.anchors = a;
218	    void bkModelLoad();
219	    late!.then((src) => { if (src && !this.disposed) this.swap(src); });   // không bao giờ từ chối
220	  }
221	
222	  /* Có mô hình thật chưa */
223	  get real(): boolean { return this.root !== null; }
224	
225	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
226	  private swap(src: BkSource): void {
227	    if (this.root || this.disposed) return;
228	    const root = src.scene.clone();
229	    this.src = src;
230	    this.front = root.getObjectByName('front')!; this.wheelF = root.getObjectByName('wheel_f')!; this.wheelR = root.getObjectByName('wheel_r')!;
231	    this.frontQ0.copy(this.front.quaternion); this.frontP0.copy(this.front.position);
232	    this.wfQ0.copy(this.wheelF.quaternion); this.wfP0.copy(this.wheelF.position);
233	    this.wrQ0.copy(this.wheelR.quaternion); this.wrP0.copy(this.wheelR.position);
234	    this.axisF.copy(src.axis).applyQuaternion(_q.copy(this.frontQ0).invert());
235	    this.dashMat = bkDashMaterial();
236	    root.traverse((o) => {
237	      const m = o as THREE.Mesh;
238	      if (!m.isMesh) return;
239	      const mat = m.material as THREE.Material;
240	      if (mat.name === 'dash') m.material = this.dashMat!;
241	      else if (mat === src.tail) this.tailMeshes.push(m);
242	      else if (mat === src.sigL) this.sigLMeshes.push(m);
243	      else if (mat === src.sigR) this.sigRMeshes.push(m);
244	    });
245	    for (const [k] of ANCHORS) this.anchors[k].removeFromParent();
246	    const a = {} as BkAnchors;
247	    for (const [k, n] of ANCHORS) a[k] = root.getObjectByName(n)!;
248	    this.anchors = a;
249	    this.root = root;
250	    this.roll.add(root);
251	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
252	    this.brakingNow = false; this.sigLNow = false; this.sigRNow = false;
253	    if (this.placed) this.place(this.last);
254	  }
255	
256	  place(p: BkPlace): void {
257	    const l = this.last;
258	    if (p !== l) { l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.lean = p.lean; l.steer = p.steer; l.wheel = p.wheel; l.susF = p.susF; l.susR = p.susR; l.braking = p.braking; l.sig = p.sig; }
259	    this.placed = true;
260	    const g = this.group;
261	    g.position.set(p.x, p.y, p.z);
262	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(_q.setFromAxisAngle(AXZ, p.pitch));
263	    this.roll.rotation.x = -p.lean;                                  // lean > 0 nghiêng trái (−Z cục bộ)
264	    const root = this.root;
265	    if (!root) return;
266	    const front = this.front!, wf = this.wheelF!, wr = this.wheelR!;
267	    /* cổ lái: xoay quanh trục (kẹp góc khóa lái); bánh trước trượt dọc trục theo susF */
268	    const st = p.steer > M.steerLock ? M.steerLock : p.steer < -M.steerLock ? -M.steerLock : p.steer === p.steer ? p.steer : 0;
269	    front.quaternion.setFromAxisAngle(this.src!.axis, st).multiply(this.frontQ0);
270	    wf.position.copy(this.axisF).multiplyScalar(p.susF).add(this.wfP0);
271	    wr.position.set(this.wrP0.x, this.wrP0.y + p.susR, this.wrP0.z);
272	    /* bánh lăn quanh Z cục bộ: xe tiến thì góc âm */
273	    wf.quaternion.copy(this.wfQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
274	    wr.quaternion.copy(this.wrQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
275	    /* phần trên lò xo: xoay φ quanh Z, dời ty sao cho hai tâm bánh về độ cao nghỉ của bánh sau (bánh chạm đất) */
276	    _v.copy(wf.position).applyQuaternion(front.quaternion).add(this.frontP0);   // tâm bánh trước trong hệ root
277	    const xf = _v.x, yf = _v.y, xr = wr.position.x, yr = wr.position.y;
278	    const phi = Math.atan2(yr - yf, xf - xr), sn = Math.sin(phi), cs = Math.cos(phi);
279	    root.rotation.set(0, 0, phi);
280	    root.position.set(0, this.wrP0.y - (xr * sn + yr * cs), 0);
281	    /* đèn: phanh, xi nhan (nửa chu kỳ đầu sáng) */
282	    if (p.braking !== this.brakingNow) {
283	      this.brakingNow = p.braking;
284	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
285	      for (const m of this.tailMeshes) m.material = mat;
286	    }
287	    const ph = shared.uTime.value * M.sigHz, blink = ph - Math.floor(ph) < 0.5;
288	    const onL = p.sig === 1 && blink, onR = p.sig === -1 && blink;
289	    if (onL !== this.sigLNow) { this.sigLNow = onL; const mat = onL ? this.src!.sigLOn : this.src!.sigL; for (const m of this.sigLMeshes) m.material = mat; }
290	    if (onR !== this.sigRNow) { this.sigRNow = onR; const mat = onR ? this.src!.sigROn : this.src!.sigR; for (const m of this.sigRMeshes) m.material = mat; }
291	  }
292	
293	  dispose(): void {
294	    if (this.disposed) return;
295	    this.disposed = true;
296	    this.group.removeFromParent();
297	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; }
298	    this.tempGeo?.dispose(); this.tempGeo = null;
299	    this.dashMat?.dispose(); this.dashMat = null;
300	    if (this.root) { this.roll.remove(this.root); this.root = null; }
301	    this.tailMeshes.length = 0; this.sigLMeshes.length = 0; this.sigRMeshes.length = 0;
302	  }
303	}
