50	  clav: THREE.Object3D | null; up: THREE.Object3D; fore: THREE.Object3D; hand: THREE.Object3D;
51	  l1: number; l2: number;             // m dài cánh tay, cẳng tay
52	  dU: THREE.Vector3; nU: THREE.Vector3;   // trục xương / trục bản lề trong hệ cục bộ cánh tay
53	  dF: THREE.Vector3; nF: THREE.Vector3;   // như trên cho cẳng tay
