63	export class PlBones {
64	  readonly root: THREE.Object3D;
65	  readonly pelvis: THREE.Object3D; readonly spines: THREE.Object3D[]; readonly neck: THREE.Object3D | null; readonly head: THREE.Object3D;
66	  readonly thigh: THREE.Object3D[]; readonly calf: THREE.Object3D[]; readonly foot: (THREE.Object3D | null)[];
67	  readonly arms: PlArm[];
68	  pack: THREE.Object3D | null = null;     // xương phụ ba lô (con của Spine2, rig.ts gắn)
69	  private touched: THREE.Object3D[] = [];
70	  private base: THREE.Quaternion[] = [];
71	
72	  constructor(root: THREE.Object3D) {
73	    this.root = root;
74	    const need = (s: string): THREE.Object3D => { const o = find(root, s); if (!o) throw new Error('thiếu xương ' + s); return o; };
75	    this.pelvis = need('Pelvis');
76	    this.spines = [need('Spine'), need('Spine1'), need('Spine2')];
77	    this.neck = find(root, 'Neck'); this.head = need('Head');
78	    this.thigh = [need('L Thigh'), need('R Thigh')]; this.calf = [need('L Calf'), need('R Calf')]; this.foot = [find(root, 'L Foot'), find(root, 'R Foot')];
79	    this.arms = (['L', 'R'] as const).map((s, i) => {
80	      const fingers: THREE.Object3D[][] = [];
81	      for (let f = 0; f < 5; f++) {
82	        const ch: THREE.Object3D[] = [];
83	        for (const sfx of ['', '1', '2']) { const o = find(root, `${s} Finger${f}${sfx}`); if (o) ch.push(o); else break; }
84	        fingers.push(ch);
85	      }
86	      return {
87	        side: (i ? 1 : -1) as -1 | 1, clav: find(root, `${s} Clavicle`), up: need(`${s} UpperArm`), fore: need(`${s} Forearm`), hand: need(`${s} Hand`),
88	        l1: 0.28, l2: 0.26, dU: new THREE.Vector3(1, 0, 0), nU: new THREE.Vector3(0, 0, 1), dF: new THREE.Vector3(1, 0, 0), nF: new THREE.Vector3(0, 0, 1),
89	        fH: new THREE.Vector3(1, 0, 0), nH: new THREE.Vector3(0, -1, 0), gH: new THREE.Vector3(0.08, 0, 0), fingers,
90	        D: new THREE.Quaternion(), hasD: false, target: new THREE.Vector3(), elbow: [0, 0, 0], end: [0, 0, 0]
91	      };
92	    });
93	    const add = (o: THREE.Object3D | null) => { if (o && !this.touched.includes(o)) { this.touched.push(o); this.base.push(o.quaternion.clone()); } };
94	    add(this.pelvis); this.spines.forEach(add); add(this.neck); add(this.head);
95	    this.thigh.forEach(add); this.calf.forEach(add); this.foot.forEach(add);
96	    for (const a of this.arms) { add(a.clav); add(a.up); add(a.fore); add(a.hand); for (const ch of a.fingers) ch.forEach(add); }
97	  }
