161	  /* Áp tư thế: pose (react.ts, góc cộng thêm) + đích hai quai phanh tL / tR (điểm nắm, hệ C) */
162	  apply(p: PlPose, tL: THREE.Vector3, tR: THREE.Vector3): void {
163	    const P = CONFIG.explore.pilot, B = P.base;
164	    /* 1) hông ngả ra sau: xoay quanh +Z dương đưa thân trên về −X, đùi nâng lên (bù ở bước 4) */
165	    this.rotE(this.pelvis, 0, 0, B.recline);
166	    /* 2) ba đốt sống: nghiêng trái = quay âm quanh +X, chúi trước = quay âm quanh +Z, vai xoay trái = quay dương quanh +Y */
167	    const k = 1 / this.spines.length;
168	    for (const s of this.spines) this.rotE(s, -p.spineRoll * k, p.spineTwist * k, -(p.spinePitch + B.spine) * k);
169	    /* 3) đầu: quay, nghiêng bù, cúi nhìn trước (bù độ ngả) */
170	    this.rotE(this.neck, 0, 0, -B.neck);
171	    this.rotE(this.head, -p.headRoll, p.headYaw, -B.head);
172	    /* 4) chân: đùi (dạng: trái quay dương quanh +Y; đưa ngang theo legSide; gập hông quanh +Z), gối (gập = quay âm quanh +Z), bàn chân */
173	    for (let i = 0; i < 2; i++) {
174	      const side = i ? 1 : -1, knee = i ? p.kneeR : p.kneeL;
175	      this.rotE(this.thigh[i], 0, p.legSide - side * (p.legSplit + B.legSplit), B.hip + p.legFore * B.legForeHip);
176	      this.rotE(this.calf[i], 0, 0, -(B.knee + knee) + p.legFore);
177	      this.rotE(this.foot[i], 0, 0, B.foot);
178	    }
179	    /* 5) xương đòn nâng vai khi tay lên quai: trái quay dương quanh +X */
180	    for (const a of this.arms) this.rotE(a.clav, -a.side * B.clavicle, 0, B.clavicleFore);
181	    /* 6) ba lô (xương phụ con của Spine2): nghiêng trái = âm quanh +X, chúi trước = âm quanh +Z */
182	    if (this.pack) {
183	      this.pack.quaternion.identity();
184	      this.rotE(this.pack, -p.packRoll, 0, -p.packPitch);
185	    }
186	    /* 7) tay */
187	    this.updateMatrices();
188	    this.ik(this.arms[0], tL); this.ik(this.arms[1], tR);
189	  }
