157	export function setupBike(c: SwingController, onExit: () => void): void {
158	  ctrl = c; void onExit;
159	  window.addEventListener('keydown', (e) => {
160	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
161	    if (e.ctrlKey || e.metaKey || e.altKey) return;
162	    if (isField(e.target)) return;
163	    if (!BK_KEYS.has(e.code)) return;
164	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
165	    bkKeys.add(e.code);
166	    if (e.repeat) return;
167	    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
168	    if (e.code === 'KeyR') bkRecover(state!, net!);
169	    else if (e.code === 'KeyQ') bkSignal(state!, 1);
170	    else if (e.code === 'KeyE') bkSignal(state!, -1);
171	    else if (e.code === 'KeyV') bike.setView(view === 3 ? 1 : 3);
172	  });
173	  window.addEventListener('keyup', (e) => {
174	    bkKeys.delete(e.code);
175	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
176	  });
177	  const drop = drBindDrop(window, document, bkKeys);
178	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
179	  /* Kéo chuột trái trên canvas: xoay camera quanh xe */
180	  let dragId = -1, lx = 0, ly = 0;
181	  canvas.addEventListener('pointerdown', (e) => {
182	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
183	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
184	    canvas.setPointerCapture(e.pointerId);
185	  });
186	  canvas.addEventListener('pointermove', (e) => {
187	    if (e.pointerId !== dragId) return;
188	    drCamDrag(camS, e.clientX - lx, e.clientY - ly, K3);
189	    lx = e.clientX; ly = e.clientY;
190	  });
191	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
192	  canvas.addEventListener('pointerup', end);
193	  canvas.addEventListener('pointercancel', end);
194	  canvas.addEventListener('lostpointercapture', end);
195	}
