55	/* Tấm bóng mờ: như drShadowShared của ô tô (mép mềm hình vuông bo), cùng tham số vật liệu ⇒ cùng program */
56	function bkShadowShared(): void {
57	  if (shadowMat) return;
58	  const n = 32, d = new Uint8Array(n * n * 4);
59	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
60	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
61	    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;
62	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
63	  }
64	  const tex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); tex.needsUpdate = true;
65	  tex.magFilter = tex.minFilter = THREE.LinearFilter;
66	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: tex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
67	  shadowMat.name = 'bikeShadow';
68	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
69	}
