129	/* Làm nóng mọi thứ xe dùng: cảnh nguồn (thân, cổ lái, bánh, đèn), mặt đồng hồ (MeshBasicMaterial), hình tạm, tấm bóng. Bản đèn sáng / phanh cùng program
130	   với bản thường nên không cần. Gỡ cảnh nguồn ra (về không cha) sau khi làm nóng; chờ tối đa model.warmMs */
131	async function bkModelWarmAll(src: BkSource): Promise<void> {
132	  if (!warm) return;
133	  const g = new THREE.Group(), tg = bkTempGeometry(), dm = bkDashMaterial();
134	  g.add(new THREE.Mesh(tg, bkTempMaterial()));
135	  bkShadowShared(); g.add(new THREE.Mesh(shadowGeo!, shadowMat!));
136	  g.add(new THREE.Mesh(shadowGeo!, dm));
137	  g.add(src.scene);
138	  let timer = 0;
139	  try { await Promise.race([warm(g), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
140	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
141	  finally { clearTimeout(timer); g.remove(src.scene); tg.dispose(); dm.dispose(); }
142	}
