144	async function bkModelDefaultLoader(): Promise<THREE.Object3D> {
145	  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
146	  const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + M.url);
147	  return gltf.scene;
148	}
