150	let loader: () => Promise<THREE.Object3D> = bkModelDefaultLoader;
151	let cache: Promise<BkSource | null> | null = null;
152	let late: Promise<BkSource | null> | null = null;   // nạp không giới hạn giờ: BkBike đổi sang mô hình thật cả khi xong sau timeoutMs
153	
154	/* Nạp mô hình xe máy. Không bao giờ ném / từ chối: lỗi hoặc quá model.timeoutMs → warn một lần, null.
155	   Quá giờ chỉ là câu trả lời của bkModelLoad: việc nạp vẫn chạy tiếp, xe đang có (BkBike) đổi sang mô hình thật khi nó xong (late) */
156	export function bkModelLoad(): Promise<BkSource | null> {
157	  if (cache) return cache;
158	  const work = (async () => {
159	    const src = bkModelSource(await loader());
160	    await bkModelWarmAll(src);
161	    return src;
162	  })();
163	  const LATE = {} as BkSource;   // dấu quá giờ
164	  let timer = 0;
165	  const p = Promise.race([work, new Promise<BkSource>((r) => { timer = setTimeout(() => r(LATE), M.timeoutMs) as unknown as number; })])
166	    .then((s) => { if (s !== LATE) return s; console.warn(`Lái xe máy: nạp mô hình xe quá ${M.timeoutMs} ms, dùng hình tạm`); return null; },
167	      (e) => { console.warn('Lái xe máy: không nạp được mô hình xe, dùng hình tạm', e); return null; })
168	    .finally(() => clearTimeout(timer));
169	  late = work.catch(() => null);   // lỗi đã báo ở nhánh race
170	  cache = p;
171	  return p;
172	}
