180	export class BkBike {
181	  readonly group = new THREE.Group();
182	  private readonly roll = new THREE.Group();                         // nút cuộn lean quanh đường chạm đất
183	  anchors: BkAnchors;
184	  dashMat: THREE.MeshBasicMaterial | null = null;
185	  private temp: THREE.Mesh | null;
186	  private tempGeo: THREE.BufferGeometry | null;
187	  private disposed = false;
188	  private src: BkSource | null = null;
189	  private root: THREE.Object3D | null = null;                        // bản sao `scooter`: phần trên lò xo
190	  private front: THREE.Object3D | null = null;
191	  private wheelF: THREE.Object3D | null = null;
192	  private wheelR: THREE.Object3D | null = null;
193	  private readonly frontQ0 = new THREE.Quaternion(); private readonly wfQ0 = new THREE.Quaternion(); private readonly wrQ0 = new THREE.Quaternion();
194	  private readonly frontP0 = new THREE.Vector3(); private readonly wfP0 = new THREE.Vector3(); private readonly wrP0 = new THREE.Vector3();
195	  private readonly axisF = new THREE.Vector3();                      // trục cổ lái trong hệ cục bộ của front lúc nghỉ
196	  private tailMeshes: THREE.Mesh[] = []; private sigLMeshes: THREE.Mesh[] = []; private sigRMeshes: THREE.Mesh[] = [];
197	  private brakingNow = false; private sigLNow = false; private sigRNow = false;
198	  private readonly last: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
199	  private placed = false;
200	
201	  constructor() {
202	    this.group.name = 'bike';
203	    this.group.add(this.roll);
204	    this.tempGeo = bkTempGeometry();
205	    this.temp = new THREE.Mesh(this.tempGeo, bkTempMaterial());
206	    this.temp.name = 'bike-temp';
207	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
208	    this.roll.add(this.temp);
209	    bkShadowShared();
210	    const sh = new THREE.Mesh(shadowGeo!, shadowMat!);
211	    sh.scale.set(B.length + 2 * M.shadow.pad, 1, B.width + 2 * M.shadow.pad);
212	    sh.position.y = M.shadow.lift;
213	    sh.layers.set(1); sh.castShadow = false; sh.receiveShadow = false; sh.renderOrder = 1;
214	    this.group.add(sh);
215	    const a = {} as BkAnchors;
216	    for (const [k, n] of ANCHORS) { const o = new THREE.Object3D(); o.name = 'bike-temp-' + n; this.roll.add(o); a[k] = o; }
217	    this.anchors = a;
218	    void bkModelLoad();
219	    late!.then((src) => { if (src && !this.disposed) this.swap(src); });   // không bao giờ từ chối
220	  }
221	
222	  /* Có mô hình thật chưa */
223	  get real(): boolean { return this.root !== null; }
224	
225	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
226	  private swap(src: BkSource): void {
227	    if (this.root || this.disposed) return;
228	    const root = src.scene.clone();
229	    this.src = src;
230	    this.front = root.getObjectByName('front')!; this.wheelF = root.getObjectByName('wheel_f')!; this.wheelR = root.getObjectByName('wheel_r')!;
231	    this.frontQ0.copy(this.front.quaternion); this.frontP0.copy(this.front.position);
232	    this.wfQ0.copy(this.wheelF.quaternion); this.wfP0.copy(this.wheelF.position);
233	    this.wrQ0.copy(this.wheelR.quaternion); this.wrP0.copy(this.wheelR.position);
234	    this.axisF.copy(src.axis).applyQuaternion(_q.copy(this.frontQ0).invert());
235	    this.dashMat = bkDashMaterial();
236	    root.traverse((o) => {
237	      const m = o as THREE.Mesh;
238	      if (!m.isMesh) return;
239	      const mat = m.material as THREE.Material;
240	      if (mat.name === 'dash') m.material = this.dashMat!;
241	      else if (mat === src.tail) this.tailMeshes.push(m);
242	      else if (mat === src.sigL) this.sigLMeshes.push(m);
243	      else if (mat === src.sigR) this.sigRMeshes.push(m);
244	    });
245	    for (const [k] of ANCHORS) this.anchors[k].removeFromParent();
246	    const a = {} as BkAnchors;
247	    for (const [k, n] of ANCHORS) a[k] = root.getObjectByName(n)!;
248	    this.anchors = a;
249	    this.root = root;
250	    this.roll.add(root);
251	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
252	    this.brakingNow = false; this.sigLNow = false; this.sigRNow = false;
253	    if (this.placed) this.place(this.last);
254	  }
255	
256	  place(p: BkPlace): void {
257	    const l = this.last;
258	    if (p !== l) { l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.lean = p.lean; l.steer = p.steer; l.wheel = p.wheel; l.susF = p.susF; l.susR = p.susR; l.braking = p.braking; l.sig = p.sig; }
259	    this.placed = true;
260	    const g = this.group;
261	    g.position.set(p.x, p.y, p.z);
262	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(_q.setFromAxisAngle(AXZ, p.pitch));
263	    this.roll.rotation.x = -p.lean;                                  // lean > 0 nghiêng trái (−Z cục bộ)
264	    const root = this.root;
265	    if (!root) return;
266	    const front = this.front!, wf = this.wheelF!, wr = this.wheelR!;
267	    /* cổ lái: xoay quanh trục (kẹp góc khóa lái); bánh trước trượt dọc trục theo susF */
268	    const st = p.steer > M.steerLock ? M.steerLock : p.steer < -M.steerLock ? -M.steerLock : p.steer === p.steer ? p.steer : 0;
269	    front.quaternion.setFromAxisAngle(this.src!.axis, st).multiply(this.frontQ0);
270	    wf.position.copy(this.axisF).multiplyScalar(p.susF).add(this.wfP0);
271	    wr.position.set(this.wrP0.x, this.wrP0.y + p.susR, this.wrP0.z);
272	    /* bánh lăn quanh Z cục bộ: xe tiến thì góc âm */
273	    wf.quaternion.copy(this.wfQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
274	    wr.quaternion.copy(this.wrQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
275	    /* phần trên lò xo: xoay φ quanh Z, dời ty sao cho hai tâm bánh về độ cao nghỉ của bánh sau (bánh chạm đất) */
276	    _v.copy(wf.position).applyQuaternion(front.quaternion).add(this.frontP0);   // tâm bánh trước trong hệ root
277	    const xf = _v.x, yf = _v.y, xr = wr.position.x, yr = wr.position.y;
278	    const phi = Math.atan2(yr - yf, xf - xr), sn = Math.sin(phi), cs = Math.cos(phi);
279	    root.rotation.set(0, 0, phi);
280	    root.position.set(0, this.wrP0.y - (xr * sn + yr * cs), 0);
281	    /* đèn: phanh, xi nhan (nửa chu kỳ đầu sáng) */
282	    if (p.braking !== this.brakingNow) {
283	      this.brakingNow = p.braking;
284	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
285	      for (const m of this.tailMeshes) m.material = mat;
286	    }
287	    const ph = shared.uTime.value * M.sigHz, blink = ph - Math.floor(ph) < 0.5;
288	    const onL = p.sig === 1 && blink, onR = p.sig === -1 && blink;
289	    if (onL !== this.sigLNow) { this.sigLNow = onL; const mat = onL ? this.src!.sigLOn : this.src!.sigL; for (const m of this.sigLMeshes) m.material = mat; }
290	    if (onR !== this.sigRNow) { this.sigRNow = onR; const mat = onR ? this.src!.sigROn : this.src!.sigR; for (const m of this.sigRMeshes) m.material = mat; }
291	  }
292	
293	  dispose(): void {
294	    if (this.disposed) return;
295	    this.disposed = true;
296	    this.group.removeFromParent();
297	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; }
298	    this.tempGeo?.dispose(); this.tempGeo = null;
299	    this.dashMat?.dispose(); this.dashMat = null;
300	    if (this.root) { this.roll.remove(this.root); this.root = null; }
301	    this.tailMeshes.length = 0; this.sigLMeshes.length = 0; this.sigRMeshes.length = 0;
302	  }
303	}
