const tick = () => new Promise((r) => setTimeout(r, 0));
const pilotOf = (g: THREE.Group) => g.children.find((c) => c.name === 'ex-pilot');
const wingGeo = (g: THREE.Group) => (g.children[0] as THREE.Mesh).geometry;

