  r.setFirstPerson(true); r.update(b, sig(), 1 / 60);
  assert.ok(head.scale.x < 1e-3 && head.scale.y < 1e-3 && head.scale.z < 1e-3);
  r.setFirstPerson(false); r.update(b, sig(), 1 / 60);
  assert.deepEqual(head.scale.toArray(), [1, 1, 1]);
