  const H = RC.helmet, g = new THREE.SphereGeometry(H.r, 20, 8, 0, TAU, 0, Math.PI / 2);
  const c = new THREE.Color(H.color), n = g.getAttribute('position').count, col = new Float32Array(n * 3);
